import{_ as a,c as o,o as i,a3 as t}from"./chunks/framework.CoV49S2T.js";const h=JSON.parse('{"title":"Privacy Policy","description":"","frontmatter":{},"headers":[],"relativePath":"guide/privacy.md","filePath":"guide/privacy.md","lastUpdated":1787284674000}'),r={name:"guide/privacy.md"};function s(l,e,n,c,d,u){return i(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to &quot;Privacy Policy&quot;">​</a></h1><p>ClipboxAI is a smart clipboard manager for macOS. Your privacy is our priority.</p><h2 id="local-first-design" tabindex="-1">Local-First Design <a class="header-anchor" href="#local-first-design" aria-label="Permalink to &quot;Local-First Design&quot;">​</a></h2><ul><li>Your clipboard history is stored entirely on your Mac.</li><li>Built-in local actions (extract links, count stats, collapse blank lines, and on-device ML suggestions) run fully offline.</li><li>No account or registration is required to use the core app.</li><li>No internet connection is required for local clipboard management and on-device features.</li></ul><h2 id="cloud-ai-optional" tabindex="-1">Cloud AI (Optional) <a class="header-anchor" href="#cloud-ai-optional" aria-label="Permalink to &quot;Cloud AI (Optional)&quot;">​</a></h2><p>ClipboxAI can optionally use cloud AI providers (such as DeepSeek, MiniMax, GLM, Kimi, Mistral, or a local Ollama server) to power advanced actions like summarize, translate, and custom prompts.</p><ul><li>When enabled, the selected text or clipboard content is sent <strong>directly to the provider you configure</strong>, using <strong>your own API key</strong>.</li><li>Your API key is stored only in your Mac&#39;s Keychain and is never uploaded to us.</li><li>You can disable cloud AI at any time and continue using local features.</li><li>Clipboard history is <strong>not</strong> sent to the cloud automatically; cloud requests are triggered only when you run a cloud action.</li></ul><h2 id="what-we-do-not-collect" tabindex="-1">What We Do Not Collect <a class="header-anchor" href="#what-we-do-not-collect" aria-label="Permalink to &quot;What We Do Not Collect&quot;">​</a></h2><ul><li>We do not collect your clipboard contents, documents, or files.</li><li>We do not track your activity, browsing behavior, or usage patterns.</li><li>We do not operate any server that receives your clipboard data.</li><li>We do not include third-party analytics, advertising, or tracking SDKs.</li><li>We do not have any telemetry system.</li></ul><h2 id="what-data-is-stored-locally" tabindex="-1">What Data Is Stored Locally <a class="header-anchor" href="#what-data-is-stored-locally" aria-label="Permalink to &quot;What Data Is Stored Locally&quot;">​</a></h2><p>The following data is stored only on your device:</p><ul><li><strong>Clipboard history</strong>: Recent items for quick access (kept on your Mac).</li><li><strong>App settings</strong>: Theme, language preference, enabled actions, provider configuration.</li><li><strong>API keys</strong>: Stored securely in the local Keychain (only if you configure a cloud provider).</li><li><strong>Custom actions</strong>: Prompts and configuration you create.</li><li><strong>Logs</strong>: Debug logs for troubleshooting (can be deleted at any time).</li></ul><h2 id="permissions-used-by-the-app" tabindex="-1">Permissions Used by the App <a class="header-anchor" href="#permissions-used-by-the-app" aria-label="Permalink to &quot;Permissions Used by the App&quot;">​</a></h2><ul><li><strong>Accessibility / Full Disk Access</strong>: Required to read the system clipboard and provide global shortcuts.</li><li><strong>Notifications</strong>: Optional, for completion alerts on long-running cloud requests.</li></ul><p>You can manage these permissions in <strong>System Settings → Privacy &amp; Security</strong> at any time.</p><h2 id="in-app-purchases-license" tabindex="-1">In-App Purchases / License <a class="header-anchor" href="#in-app-purchases-license" aria-label="Permalink to &quot;In-App Purchases / License&quot;">​</a></h2><p>License purchases (if any) are processed by Apple via the Mac App Store. ClipboxAI does not receive or store your payment information. License receipts are stored locally to verify ownership.</p><h2 id="third-party-services" tabindex="-1">Third-Party Services <a class="header-anchor" href="#third-party-services" aria-label="Permalink to &quot;Third-Party Services&quot;">​</a></h2><p>ClipboxAI itself does not include any third-party analytics, advertising, or tracking services. When you enable a cloud AI provider, your requests are handled by that provider under its own privacy policy.</p><h2 id="privacy-requests" tabindex="-1">Privacy Requests <a class="header-anchor" href="#privacy-requests" aria-label="Permalink to &quot;Privacy Requests&quot;">​</a></h2><p>Since ClipboxAI stores all data locally on your device, we do not hold any personal data on our servers. If you have questions about privacy, please contact us.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>For privacy questions, open an issue at <a href="https://github.com/clipboxAI/clipboard-site/issues" target="_blank" rel="noreferrer">GitHub Issues</a> or email us at <a href="mailto:clipboxai@w3cub.com" target="_blank" rel="noreferrer">clipboxai@w3cub.com</a>.</p>',23)])])}const y=a(r,[["render",s]]);export{h as __pageData,y as default};
